#dc {
    --ink: #172c39;
    --muted: #617581;
    --line: #dce6eb;
    --teal: #007e80;
    --bg: #f3f7f9;
    --card: #ffffff;
    --good: #2e9e5b;
    --warn: #e0962c;
    --bad: #d1462f;
    --none: #a9bcc5;
    color: var(--ink);
    font: 15px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
    background: var(--bg);
    padding: 12px;
    border-radius: 10px;
    max-width: 1200px;
    margin: 0 auto
}

#dc * {
    box-sizing: border-box
}

#dc button,
#dc input {
    font: inherit
}

/* Header */
#dc .dc-head {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 10px;
    justify-content: space-between;
    margin-bottom: 8px
}

#dc .dc-brand strong {
    display: block;
    font-size: 21px;
    line-height: 1.2
}

#dc .dc-eyebrow {
    display: block;
    color: var(--teal);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 1.5px
}

#dc .dc-muted {
    color: var(--muted);
    font-size: 13px
}

#dc .dc-nav {
    display: flex;
    gap: 6px;
    align-items: center
}

#dc .dc-nav button,
#dc .dc-tools button {
    border: 0;
    border-radius: 8px;
    background: var(--teal);
    color: #fff;
    min-width: 40px;
    height: 40px;
    padding: 0 12px;
    cursor: pointer;
    font-size: 15px
}

#dc .dc-nav button {
    font-size: 22px;
    line-height: 1
}

#dc .dc-tools {
    display: flex;
    gap: 6px
}

#dc .dc-tools .dc-ghost {
    background: #fff;
    color: var(--teal);
    border: 1px solid #b9d6d7
}

#dc .dc-tools .dc-ghost[aria-pressed="true"] {
    background: var(--teal);
    color: #fff
}

#dc button:disabled {
    opacity: .45;
    cursor: default
}

#dc input[type="date"] {
    height: 40px;
    border: 1px solid #cbdbe1;
    border-radius: 8px;
    padding: 0 8px;
    background: #fff;
    color: var(--ink)
}

#dc #dc-message {
    margin: 0 0 10px;
    padding: 8px 12px;
    background: #e5f2f2;
    border-radius: 8px;
    font-size: 14px
}

#dc #dc-message.flag {
    background: #fdecc8;
    color: #6f4a00
}

/* Card grid: one column on phones, more on wider screens */
#dc .dc-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 10px
}

@media (min-width: 560px) {
    #dc .dc-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr))
    }
}

@media (min-width: 900px) {
    #dc .dc-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr))
    }
}

@media (min-width: 1150px) {
    #dc .dc-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr))
    }
}

#dc .dc-section {
    grid-column: 1 / -1;
    margin: 8px 2px -2px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 1.5px;
    color: var(--muted)
}

/* Flip cards */
#dc .dc-card {
    perspective: 1000px;
    height: 220px;
    cursor: pointer;
    outline: none
}

#dc .dc-inner {
    position: relative;
    height: 100%;
    transition: transform .5s;
    transform-style: preserve-3d
}

#dc .dc-card.flipped .dc-inner {
    transform: rotateY(180deg)
}

#dc .dc-face {
    position: absolute;
    inset: 0;
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
    background: var(--card);
    border: 1px solid var(--line);
    border-left: 5px solid var(--none);
    border-radius: 12px;
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    box-shadow: 0 1px 2px rgba(23, 44, 57, .06)
}

#dc .dc-back {
    transform: rotateY(180deg);
    overflow: auto
}

#dc .dc-card.good .dc-face {
    border-left-color: var(--good)
}

#dc .dc-card.warn .dc-face {
    border-left-color: var(--warn)
}

#dc .dc-card.bad .dc-face {
    border-left-color: var(--bad)
}

#dc .dc-card:focus-visible .dc-face {
    outline: 3px solid #54b7d0;
    outline-offset: 2px
}

#dc .dc-top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 8px
}

#dc .dc-label {
    font-size: 12px;
    font-weight: 700;
    letter-spacing: .6px;
    text-transform: uppercase;
    color: var(--muted)
}

#dc .dc-pill {
    font-size: 11px;
    font-weight: 700;
    border-radius: 999px;
    padding: 2px 8px;
    white-space: nowrap;
    background: #eef3f5;
    color: var(--muted)
}

#dc .good .dc-pill {
    background: #e2f4ea;
    color: #1f7a45
}

#dc .warn .dc-pill {
    background: #fcefd9;
    color: #8a5a00
}

#dc .bad .dc-pill {
    background: #fbe3df;
    color: #a3301d
}

#dc .dc-value {
    font-size: 34px;
    font-weight: 700;
    line-height: 1.1;
    margin: 14px 0 4px;
    font-variant-numeric: tabular-nums;
    letter-spacing: -.5px
}

#dc .dc-value small {
    font-size: 16px;
    font-weight: 600;
    color: var(--muted);
    margin-left: 4px;
    letter-spacing: 0
}

#dc .dc-sub {
    font-size: 14px;
    color: #34495a
}

#dc .dc-hint {
    margin-top: auto;
    font-size: 12px;
    color: var(--muted)
}

/* Card backs */
#dc .dc-back .dc-label {
    margin-bottom: 6px
}

#dc .dc-mini {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px
}

#dc .dc-mini th {
    text-align: right;
    font-size: 11px;
    font-weight: 600;
    color: var(--muted);
    padding: 2px 4px;
    border-bottom: 1px solid var(--line)
}

#dc .dc-mini th:first-child,
#dc .dc-mini td:first-child {
    text-align: left
}

#dc .dc-mini td {
    padding: 3px 4px;
    text-align: right;
    border-bottom: 1px solid #eef3f5;
    font-variant-numeric: tabular-nums
}

#dc .dc-mini td:first-child {
    max-width: 150px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

#dc .dc-mini tr.total td {
    font-weight: 700;
    border-top: 1px solid #b8c8cf
}

#dc .dc-note {
    font-size: 12px;
    color: var(--muted);
    margin-top: 6px
}

#dc .dc-list {
    margin: 0;
    padding: 0;
    list-style: none;
    font-size: 13px
}

#dc .dc-list li {
    padding: 4px 0;
    border-bottom: 1px solid #eef3f5
}

#dc .dc-list b {
    display: block;
    font-size: 11px;
    color: var(--muted);
    font-weight: 600
}

#dc .dc-bar {
    display: grid;
    grid-template-columns: 82px 1fr 46px;
    gap: 6px;
    align-items: center;
    font-size: 12px;
    margin: 4px 0
}

#dc .dc-bar i {
    display: block;
    height: 10px;
    border-radius: 5px;
    background: var(--teal)
}

#dc .dc-bar span:last-child {
    text-align: right;
    font-variant-numeric: tabular-nums
}

#dc .dc-error .dc-face {
    border-left-color: var(--bad)
}

#dc .dc-foot {
    margin: 12px 2px 0
}

@media (max-width: 420px) {
    #dc {
        padding: 8px;
        border-radius: 0
    }

    #dc .dc-head {
        gap: 8px
    }

    /* Date bar and buttons each take a full row on phones */
    #dc .dc-brand,
    #dc .dc-nav,
    #dc .dc-tools {
        flex: 1 1 100%
    }

    #dc .dc-nav input {
        flex: 1;
        min-width: 0
    }

    #dc .dc-tools button {
        flex: 1
    }

    #dc .dc-card {
        height: 200px
    }

    #dc .dc-value {
        font-size: 32px;
        margin-top: 10px
    }
}

@media (prefers-reduced-motion: reduce) {
    #dc .dc-inner {
        transition: none
    }
}

